    --success-fg: #b9f0c9;
    --error-bg: #3a1414;
    --error-fg: #ffc4c4;
    --focus: #9ab4ff;
    --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 8px 24px rgba(0, 0, 0, 0.4);
  }
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute;
  top: -40px;
  left: 12px;
  background: var(--accent);
  color: var(--accent-contrast);
  padding: 8px 12px;
  border-radius: 8px;
  text-decoration: none;
  z-index: 10;
}
.skip-link:focus { top: 12px; outline: 3px solid var(--focus); outline-offset: 2px; }

.page {
  max-width: 680px;
  margin: 0 auto;
  padding: 48px 20px 80px;
}

.page__header { margin-bottom: 28px; }

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--accent);
  margin: 0 0 8px;
}

h1 {
  font-size: clamp(1.7rem, 2.4vw + 1rem, 2.25rem);
  margin: 0 0 8px;
  letter-spacing: -0.01em;
}

.lede {
  margin: 0;
  color: var(--muted);
  max-width: 56ch;
}

.quiz {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 8px 24px 24px;
  box-shadow: var(--shadow);
}

.form-field { padding: 20px 0; border-bottom: 1px solid var(--border); }
.form-field:last-of-type { border-bottom: none; }

fieldset {
  border: 0;
  padding: 0;
  margin: 0;
}

legend {
  font-size: 1.05rem;
  font-weight: 600;
  margin-bottom: 6px;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: baseline;
}

.q-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.6em;
  height: 1.6em;
  padding: 0 0.4em;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  color: var(--accent);
  font-size: 0.8rem;
  font-weight: 700;
}

.req { color: var(--accent); margin-left: 2px; }

.help-text {
  margin: 0 0 12px;
  color: var(--muted);
  font-size: 0.92rem;
}

.options {
  list-style: none;
  margin: 12px 0 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.options li {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  transition: border-color 120ms ease, background-color 120ms ease, box-shadow 120ms ease;
}

.options li:hover { border-color: var(--border-strong); }

.options li:has(input:checked) {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
}

.options li:has(input:focus-visible) {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.options input[type="checkbox"] {
  width: 20px;
  height: 20px;
  margin: 0;
  accent-color: var(--accent);
  flex: 0 0 auto;
  cursor: pointer;
}

.options label {
  cursor: pointer;
  flex: 1;
  user-select: none;
}

.error-text {
  margin: 12px 0 0;
  color: var(--error-fg);
  background: var(--error-bg);
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 0.92rem;
  font-weight: 500;
}

.actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  padding-top: 20px;
}

button {
  font: inherit;
  cursor: pointer;
  border-radius: 10px;
  padding: 12px 20px;
  border: 1px solid transparent;
  font-weight: 600;
  transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease;
}

.btn-primary {
  background: var(--accent);
  color: var(--accent-contrast);
}
.btn-primary:hover { background: var(--accent-hover); }

.btn-secondary {
  background: transparent;
  color: var(--text);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: color-mix(in srgb, var(--text) 6%, transparent); }

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.result {
  margin-top: 20px;
  padding: 0;
}
.result:not(:empty) {
  padding: 14px 16px;
  border-radius: 10px;
  background: var(--success-bg);
  color: var(--success-fg);
  border: 1px solid color-mix(in srgb, var(--success-fg) 25%, transparent);
}
.result.is-partial:not(:empty) {
  background: var(--error-bg);
  color: var(--error-fg);
  border-color: color-mix(in srgb, var(--error-fg) 25%, transparent);
}
.result h2 { margin: 0 0 6px; font-size: 1.05rem; }
.result p { margin: 0; }

@media (forced-colors: active) {
  .options li:has(input:checked) { border-color: Highlight; }
  .btn-primary { border-color: ButtonText; }
}
