.help-text {
  margin: 0 0 12px;
  color: var(--muted);
  font-size: 0.92rem;
}

.options {
  list-style: none;
  margin: 12px 0 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.options li {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  transition: border-color 120ms ease, background-color 120ms ease, box-shadow 120ms ease;
}

.options li:hover { border-color: var(--border-strong); }

.options li:has(input:checked) {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
}

.options li:has(input:focus-visible) {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.options input[type="checkbox"] {
  width: 20px;
  height: 20px;
  margin: 0;
  accent-color: var(--accent);
  flex: 0 0 auto;
  cursor: pointer;
}

.options label {
  cursor: pointer;
  flex: 1;
  user-select: none;
}

.error-text {
  margin: 12px 0 0;
  color: var(--error-fg);
  background: var(--error-bg);
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 0.92rem;
  font-weight: 500;
}

.actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  padding-top: 20px;
}

button {
  font: inherit;
  cursor: pointer;
  border-radius: 10px;
  padding: 12px 20px;
  border: 1px solid transparent;
  font-weight: 600;
  transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease;
}

.btn-primary {
  background: var(--accent);
  color: var(--accent-contrast);
}
.btn-primary:hover { background: var(--accent-hover); }

.btn-secondary {
  background: transparent;
  color: var(--text);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: color-mix(in srgb, var(--text) 6%, transparent); }

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.result {
  margin-top: 20px;
  padding: 0;
