}
.result h2 { margin: 0 0 6px; font-size: 1.05rem; }
.result p { margin: 0; }

@media (forced-colors: active) {
  .options li:has(input:checked) { border-color: Highlight; }
  .btn-primary { border-color: ButtonText; }
}
