  const form = document.getElementById('quiz');
  const result = document.getElementById('result');
  const questions = ['q1', 'q2', 'q3'];

  function getCheckboxes(name) {
    return Array.from(form.querySelectorAll(`input[name="${name}"]`));
  }

  function clearError(name) {
    const err = document.getElementById(`${name}-error`);
    if (!err) return;
    err.hidden = true;
    err.textContent = '';
    getCheckboxes(name).forEach(cb => cb.removeAttribute('aria-invalid'));
  }

  function setError(name, message) {
    const err = document.getElementById(`${name}-error`);
    if (!err) return;
    err.textContent = `Error: ${message}`;
    err.hidden = false;
    getCheckboxes(name).forEach(cb => cb.setAttribute('aria-invalid', 'true'));
  }

  questions.forEach(name => {
    getCheckboxes(name).forEach(cb => {
      cb.addEventListener('change', () => {
        if (getCheckboxes(name).some(c => c.checked)) clearError(name);
      });
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    result.textContent = '';
    result.classList.remove('is-partial');

    let firstInvalid = null;
    let correctCount = 0;

    questions.forEach(name => {
      const boxes = getCheckboxes(name);
      const anyChecked = boxes.some(b => b.checked);
      if (!anyChecked) {
        setError(name, 'Select at least one option.');
        if (!firstInvalid) firstInvalid = boxes[0];
      } else {
        clearError(name);
        const allMatch = boxes.every(b => b.checked === (b.dataset.correct === 'true'));
        if (allMatch) correctCount += 1;
      }
    });

    if (firstInvalid) {
      firstInvalid.focus();
      return;
    }

    const total = questions.length;
    const isPerfect = correctCount === total;
    result.classList.toggle('is-partial', !isPerfect);
    result.innerHTML = `
      <h2>${isPerfect ? 'Nice — perfect score!' : 'Quiz submitted'}</h2>
      <p>You got ${correctCount} of ${total} question${total === 1 ? '' : 's'} fully correct.</p>
    `;
  });

  form.addEventListener('reset', () => {
    questions.forEach(clearError);
    result.textContent = '';
    result.classList.remove('is-partial');
  });
})();
